import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 4))
    nums = draw(st.lists(st.integers(0, 3), min_size=n, max_size=n))
    q = draw(st.integers(1, 3))
    queries = []
    for _ in range(q):
        l = draw(st.integers(0, n - 1))
        r = draw(st.integers(l, n - 1))
        queries.append([l, r])
    return f"{json.dumps(nums)}\n{json.dumps(queries)}"


def validate(inp):
    try:
        lines = inp.split("\n")
        if len(lines) != 2:
            return False
        nums = json.loads(lines[0])
        queries = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(queries, list):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x <= 10**5 for x in nums):
        return False
    if not (1 <= len(queries) <= 10**5):
        return False
    for q in queries:
        if not (isinstance(q, list) and len(q) == 2):
            return False
        l, r = q
        if not (isinstance(l, int) and isinstance(r, int)):
            return False
        if not (0 <= l <= r < n):
            return False
    return True


def ref(inp):
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    queries = json.loads(lines[1])
    # Exhaustive search: each query chooses any subset of its range to decrement.
    states = {tuple(nums)}
    for l, r in queries:
        new_states = set()
        idxs = list(range(l, r + 1))
        for s in states:
            for mask in range(1 << len(idxs)):
                t = list(s)
                ok = True
                for b, idx in enumerate(idxs):
                    if mask >> b & 1:
                        t[idx] -= 1
                        if t[idx] < 0:
                            ok = False
                            break
                if ok:
                    new_states.add(tuple(t))
        states = new_states
    result = any(all(x == 0 for x in s) for s in states)
    return json.dumps(result)
