def ref(inp):
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    queries = json.loads(lines[1])
    # Each query: choose any subset of indices in [l, r] to decrement by 1.
    # Brute force over all reachable states (values must stay >= 0).
    reachable = {tuple(nums)}
    for l, r in queries:
        new_states = set()
        idxs = list(range(l, r + 1))
        for state in reachable:
            k = len(idxs)
            for mask in range(1 << k):
                ok = True
                cur = list(state)
                for b in range(k):
                    if mask >> b & 1:
                        i = idxs[b]
                        if cur[i] < 1:
                            ok = False
                            break
                        cur[i] -= 1
                if ok:
                    new_states.add(tuple(cur))
        reachable = new_states
        if not reachable:
            break
    result = any(all(v == 0 for v in s) for s in reachable)
    return json.dumps(result)
